import re
from decimal import Decimal


_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")
_MAX_AMOUNT = Decimal("1000000.00")


def parse_amount(value):
    if isinstance(value, bool):
        raise ValueError("Invalid amount type")
    if isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError("Amount must be a plain decimal string")
        value = Decimal(value)
    elif isinstance(value, int):
        value = Decimal(value)
    elif not isinstance(value, Decimal):
        raise ValueError("Invalid amount type")

    if not value.is_finite() or value <= 0 or value > _MAX_AMOUNT:
        raise ValueError("Amount must be positive and at most 1000000.00")

    # Work with the coefficient rather than quantize: no rounding and no
    # dependence on the caller's decimal precision, limits, or traps.
    _, digits, exponent = value.as_tuple()
    if exponent < -2:
        extra_places = -2 - exponent
        if extra_places >= len(digits) or any(digits[-extra_places:]):
            raise ValueError("Amount must be exactly representable in cents")
        digits = digits[:-extra_places]
    else:
        digits = digits + (0,) * (exponent + 2)
    return Decimal((0, digits, -2))


def format_amount(value):
    return format(value, ".2f")
EOF
